import raw from "@/data/capabilities.json";

/** Shape of apps/site/src/data/capabilities.json, generated by scripts/capabilities.py. */
export type Line = {
  label: string;
  source?: string;
  text?: string;
  /** How `source` was typed: plain text, or LaTeX. Absent for lines that are not expressions. */
  syntax?: "text" | "latex";
  /** For plain text: the formula as the engine read it (LaTeX, printed by the engine itself). */
  latex?: string;
};
export type Output = { label: string; latex?: string; text?: string };
export type Example = {
  id: string;
  title: string;
  op: string;
  status: string;
  input: Line[];
  assumptions: string | null;
  outputs: Output[];
  checks: string[];
  notes: string[];
};
export type Group = { id: string; title: string; summary: string };
export type Capability = {
  id: string;
  title: string;
  status: "available" | "planned";
  group: string;
  where: string[];
  needs_model: boolean;
  summary: string;
  limits: string[];
  examples: Example[];
};
type CapabilityData = { handbook_entries: number; groups: Group[]; capabilities: Capability[] };

const data = raw as unknown as CapabilityData;

export const CAPABILITIES = data.capabilities;
export const HANDBOOK_ENTRIES = data.handbook_entries;
export const GROUPS = data.groups;

/** Capabilities of one status, grouped in the order of docs/capabilities.yaml; empty groups are left out. */
export function capabilitiesByGroup(status: Capability["status"]): [Group, Capability[]][] {
  return GROUPS.map((g): [Group, Capability[]] => [
    g,
    CAPABILITIES.filter((c) => c.status === status && c.group === g.id),
  ]).filter(([, caps]) => caps.length > 0);
}

/** An example by id. Throws at build time if the record no longer has it. */
export function example(id: string): Example {
  for (const cap of CAPABILITIES) {
    const found = cap.examples.find((e) => e.id === id);
    if (found) return found;
  }
  throw new Error(`capabilities.json has no example "${id}"; regenerate or fix the page`);
}

/** The LaTeX of one output of an example, by label prefix. */
export function outputLatex(ex: Example, labelPrefix: string): string {
  const out = ex.outputs.find((o) => o.label.startsWith(labelPrefix) && o.latex);
  if (!out?.latex) throw new Error(`example "${ex.id}" has no LaTeX output "${labelPrefix}"`);
  return out.latex;
}

/** The input of an example as a formula: the engine's reading of plain text, or the LaTeX that was typed. */
export function inputLatex(ex: Example): string {
  const line = ex.input.find((l) => l.source);
  const latex = line?.latex ?? (line?.syntax === "text" ? undefined : line?.source);
  if (!latex) throw new Error(`example "${ex.id}" has no input that reads as a formula`);
  return latex;
}

export function inputSource(ex: Example): string {
  const line = ex.input.find((l) => l.source);
  if (!line?.source) throw new Error(`example "${ex.id}" has no input source`);
  return line.source;
}

const GOOD = new Set(["ok", "applicable", "verified", "stated"]);
export function statusTone(status: string): "ok" | "warn" {
  return GOOD.has(status) ? "ok" : "warn";
}
